using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer uses DateTime.UtcNow
        // at model-building time — use a fixed value for deterministic seeds.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<CosmosOrder> Orders => Set<CosmosOrder>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<CosmosOrder>(b =>
        {
            b.ToContainer("Orders");

            // EF Core 9 breaking change: The Cosmos provider now uses
            // "$type" instead of "Discriminator" by default.
            // To maintain compatibility with existing documents, explicitly
            // set the discriminator property name back to "Discriminator".
            b.HasDiscriminator<string>("Discriminator");
        });
    }

    // EF Core 9 breaking change: Synchronous I/O on Cosmos is no longer
    // supported. All queries/saves must use async methods.
    public async Task<List<CosmosOrder>> GetOrdersAsync()
        => await Orders.ToListAsync();
}

class CosmosOrder
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
    public DateTime CreatedAt { get; set; }
}

